SELECT sp.id, sp.live_room_id, sp.sec_uid, sp.start_time, sp.end_time, sp.source, sp.view_count, sp.sales_revenue, sp.refund, sp.investment, sp.refund_quantity, sp.pay_combo_cnt, sp.net_sales, sp.refund_rate, sp.roi, sp.thousand_sales, sp.exposure_count, sp.follow_count, sp.click_payment_rate, sp.interaction_rate, sp.max_online, sp.conversion_rate, sp.uv_value, sp.follow_rate FROM schedule_performance sp WHERE sp.tenant_id = #{tenantId} AND sp.is_deleted = 0
AND sp.start_time >= #{startTime}
AND sp.start_time <= #{endTime}
AND sp.live_room_id = #{liveRoomId}
AND EXISTS ( SELECT 1 FROM schedule_performance_staff sps WHERE sps.schedule_performance_id = sp.id AND sps.is_deleted = 0 AND sps.position_code = 'anchor'
AND sps.employee_name LIKE CONCAT('%', #{anchorName}, '%')
) ORDER BY sp.start_time DESC

SELECT sp.id as schedule_performance_id, sp.live_room_id, sp.start_time, sp.end_time, sps.position_id, sps.position_name, sps.employee_id, sps.employee_name FROM schedule_performance sp INNER JOIN schedule_performance_staff sps ON sp.id = sps.schedule_performance_id AND sps.tenant_id = sp.tenant_id AND sps.is_deleted = 0 WHERE sp.tenant_id = #{tenantId} AND sp.is_deleted = 0
AND sp.live_room_id IN
#{id}
AND DATE(sp.start_time) IN
#{d}

SELECT DATE(sp.start_time) AS stats_date, COUNT(DISTINCT sp.id) AS schedule_count, SUM(TIMESTAMPDIFF(MINUTE, sp.start_time, sp.end_time)) AS live_duration_minutes, SUM(sp.view_count) AS view_count, SUM(sp.sales_revenue) AS sales_revenue, SUM(sp.refund) AS refund, SUM(sp.net_sales) AS net_sales, SUM(sp.investment) AS investment, AVG(sp.roi) AS roi FROM schedule_performance sp INNER JOIN schedule_performance_staff sps ON sps.schedule_performance_id = sp.id WHERE sp.tenant_id = #{tenantId} AND sp.is_deleted = 0 AND sps.is_deleted = 0 AND sps.position_code = 'anchor' AND sp.live_room_id = #{liveRoomId}
AND sp.start_time >= #{startTime}
AND sp.end_time <= #{endTime}
AND sps.employee_name LIKE CONCAT('%', #{anchorName}, '%')
GROUP BY DATE(sp.start_time) ORDER BY
stats_date schedule_count live_duration_minutes view_count sales_revenue refund net_sales investment roi stats_date
ASC DESC

SELECT DATE(sp.start_time) AS stats_date, sps.position_id, MAX(sps.position_name) AS position_name, sps.employee_id, MAX(sps.employee_name) AS employee_name, COUNT(DISTINCT sp.id) AS schedule_count FROM schedule_performance sp INNER JOIN schedule_performance_staff sps ON sp.id = sps.schedule_performance_id AND sps.tenant_id = sp.tenant_id AND sps.is_deleted = 0 WHERE sp.tenant_id = #{tenantId} AND sp.is_deleted = 0 AND sp.live_room_id = #{liveRoomId}
AND sp.start_time >= #{startTime}
AND sp.end_time <= #{endTime}
GROUP BY DATE(sp.start_time), sps.position_id, sps.employee_id ORDER BY stats_date DESC, schedule_count DESC

SELECT
    e.id AS employee_id,
    e.name AS employee_name,
    e.user_avatar,
    e.position_id,
    e.company_id,
    e.dept_id,
    e.team_id,
    GROUP_CONCAT(DISTINCT sp.live_room_id ORDER BY sp.live_room_id) AS live_room_ids
FROM employee e
INNER JOIN schedule_performance_staff sps ON e.id = sps.employee_id AND sps.is_deleted = 0
INNER JOIN schedule_performance sp ON sps.schedule_performance_id = sp.id AND sp.is_deleted = 0
WHERE e.tenant_id = #{tenantId}
    AND e.is_deleted = 0

        AND e.company_id = #{req.companyId}


        AND e.dept_id = #{req.deptId}


        AND e.team_id = #{req.teamId}


        AND e.position_id = #{req.positionId}


        AND e.account_status = #{req.accountStatus}


        AND e.name LIKE CONCAT('%', #{req.employeeName}, '%')


        AND e.mobile = #{req.mobile}




                or e.company_id in

                    #{id}



                or e.dept_id in

                    #{id}



                or e.team_id in

                    #{id}




GROUP BY e.id
ORDER BY e.id

SELECT sps.employee_id, sp.live_room_id, COUNT(DISTINCT sp.id) AS session_count, COALESCE(SUM(TIMESTAMPDIFF(SECOND, sp.start_time, sp.end_time)) / 60, 0) AS duration, COALESCE(SUM(sp.view_count), 0) AS view_count, COALESCE(SUM(sp.sales_revenue), 0) AS sales_revenue, COALESCE(SUM(sp.refund), 0) AS refund, COALESCE(SUM(sp.net_sales), 0) AS net_sales, COALESCE(SUM(sp.investment), 0) AS investment FROM schedule_performance_staff sps INNER JOIN schedule_performance sp ON sps.schedule_performance_id = sp.id AND sp.is_deleted = 0 WHERE sp.tenant_id = #{tenantId} AND DATE(sp.start_time) BETWEEN #{startDate} AND #{endDate} AND sps.is_deleted = 0
AND sps.employee_id IN
#{id}
AND sp.live_room_id IN
#{id}
GROUP BY sps.employee_id, sp.live_room_id

SELECT DATE(sp.start_time) AS stats_date, COUNT(DISTINCT sp.id) AS schedule_count, COALESCE(SUM(TIMESTAMPDIFF(MINUTE, sp.start_time, sp.end_time)), 0) AS live_duration_minutes, COALESCE(SUM(sp.view_count), 0) AS view_count, COALESCE(SUM(sp.sales_revenue), 0) AS sales_revenue, COALESCE(SUM(sp.refund), 0) AS refund, COALESCE(SUM(sp.net_sales), 0) AS net_sales, COALESCE(SUM(sp.investment), 0) AS investment, AVG(sp.roi) AS roi, GROUP_CONCAT(DISTINCT sp.live_room_id ORDER BY sp.live_room_id) AS live_room_ids FROM schedule_performance sp INNER JOIN schedule_performance_staff sps ON sp.id = sps.schedule_performance_id AND sps.tenant_id = sp.tenant_id AND sps.is_deleted = 0 AND sps.employee_id = #{employeeId}
INNER JOIN live_room lr ON sp.live_room_id = lr.id AND lr.tenant_id = sp.tenant_id AND lr.is_deleted = 0 AND lr.anchor_name LIKE CONCAT('%', #{liveRoomName}, '%')
WHERE sp.tenant_id = #{tenantId} AND sp.is_deleted = 0
AND DATE(sp.start_time) BETWEEN #{startDate} AND #{endDate}
AND DATE(sp.start_time) >= #{startDate}
AND DATE(sp.start_time) <= #{endDate}
GROUP BY DATE(sp.start_time) ORDER BY
stats_date schedule_count live_duration_minutes view_count sales_revenue refund net_sales investment roi stats_date
ASC DESC

SELECT sp.id, sp.live_room_id, sp.start_time, sp.end_time, sp.source, sp.view_count, sp.sales_revenue, sp.refund, sp.investment, sp.refund_quantity, sp.pay_combo_cnt, sp.net_sales, sp.refund_rate, sp.roi, sp.thousand_sales, sp.exposure_count, sp.follow_count, sp.click_payment_rate, sp.interaction_rate, sp.max_online, sp.conversion_rate, sp.uv_value, sp.follow_rate FROM schedule_performance sp INNER JOIN schedule_performance_staff sps ON sp.id = sps.schedule_performance_id AND sps.tenant_id = sp.tenant_id AND sps.is_deleted = 0 AND sps.employee_id = #{employeeId}
INNER JOIN live_room lr ON sp.live_room_id = lr.id AND lr.tenant_id = sp.tenant_id AND lr.is_deleted = 0 AND lr.anchor_name LIKE CONCAT('%', #{liveRoomName}, '%')
WHERE sp.tenant_id = #{tenantId} AND sp.is_deleted = 0
AND DATE(sp.start_time) BETWEEN #{startDate} AND #{endDate}
AND DATE(sp.start_time) >= #{startDate}
AND DATE(sp.start_time) <= #{endDate}
ORDER BY
sp.start_time sp.end_time sp.view_count sp.sales_revenue sp.refund sp.net_sales sp.investment sp.roi sp.start_time
ASC DESC

SELECT
    sp.live_room_id AS liveRoomId,
    COUNT(DISTINCT CASE WHEN DATE(sp.start_time) = #{today} THEN sp.id END) AS todaySessionCount,
    COALESCE(SUM(CASE WHEN DATE(sp.start_time) = #{today}
        THEN TIMESTAMPDIFF(SECOND, sp.start_time, sp.end_time) ELSE 0 END) / 60, 0) AS todayDuration,

    COUNT(DISTINCT CASE WHEN DATE(sp.start_time) = #{yesterday} THEN sp.id END) AS yesterdaySessionCount,
    COALESCE(SUM(CASE WHEN DATE(sp.start_time) = #{yesterday}
        THEN TIMESTAMPDIFF(SECOND, sp.start_time, sp.end_time) ELSE 0 END) / 60, 0) AS yesterdayDuration,

    COUNT(DISTINCT CASE WHEN DATE(sp.start_time) BETWEEN #{thisWeekStart} AND #{today}
        THEN sp.id END) AS thisWeekSessionCount,
    COALESCE(SUM(CASE WHEN DATE(sp.start_time) BETWEEN #{thisWeekStart} AND #{today}
        THEN TIMESTAMPDIFF(SECOND, sp.start_time, sp.end_time) ELSE 0 END) / 60, 0) AS thisWeekDuration,

    COUNT(DISTINCT CASE WHEN DATE(sp.start_time) BETWEEN #{lastWeekStart} AND #{lastWeekEnd}
        THEN sp.id END) AS lastWeekSessionCount,
    COALESCE(SUM(CASE WHEN DATE(sp.start_time) BETWEEN #{lastWeekStart} AND #{lastWeekEnd}
        THEN TIMESTAMPDIFF(SECOND, sp.start_time, sp.end_time) ELSE 0 END) / 60, 0) AS lastWeekDuration,

    COUNT(DISTINCT CASE WHEN DATE(sp.start_time) BETWEEN #{thisMonthStart} AND #{today}
        THEN sp.id END) AS thisMonthSessionCount,
    COALESCE(SUM(CASE WHEN DATE(sp.start_time) BETWEEN #{thisMonthStart} AND #{today}
        THEN TIMESTAMPDIFF(SECOND, sp.start_time, sp.end_time) ELSE 0 END) / 60, 0) AS thisMonthDuration,

    COUNT(DISTINCT CASE WHEN DATE(sp.start_time) BETWEEN #{lastMonthStart} AND #{lastMonthEnd}
        THEN sp.id END) AS lastMonthSessionCount,
    COALESCE(SUM(CASE WHEN DATE(sp.start_time) BETWEEN #{lastMonthStart} AND #{lastMonthEnd}
        THEN TIMESTAMPDIFF(SECOND, sp.start_time, sp.end_time) ELSE 0 END) / 60, 0) AS lastMonthDuration
FROM schedule_performance sp
    INNER JOIN schedule_performance_staff sps ON sp.id = sps.schedule_performance_id
WHERE sp.tenant_id = #{tenantId}
  AND sp.is_deleted = 0
  AND sps.is_deleted = 0
  AND sps.position_code = 'anchor'
  AND DATE(sp.start_time) BETWEEN #{lastMonthStart} AND #{today}
  AND sp.live_room_id IN

      #{id}

GROUP BY sp.live_room_id

SELECT
    COUNT(DISTINCT CASE WHEN DATE(sp.start_time) = #{today} THEN sp.id END) AS todaySessionCount,
    COALESCE(SUM(CASE WHEN DATE(sp.start_time) = #{today}
        THEN TIMESTAMPDIFF(SECOND, sp.start_time, sp.end_time) ELSE 0 END) / 60, 0) AS todayDuration,

    COUNT(DISTINCT CASE WHEN DATE(sp.start_time) = #{yesterday} THEN sp.id END) AS yesterdaySessionCount,
    COALESCE(SUM(CASE WHEN DATE(sp.start_time) = #{yesterday}
        THEN TIMESTAMPDIFF(SECOND, sp.start_time, sp.end_time) ELSE 0 END) / 60, 0) AS yesterdayDuration,

    COUNT(DISTINCT CASE WHEN DATE(sp.start_time) BETWEEN #{thisWeekStart} AND #{today}
        THEN sp.id END) AS thisWeekSessionCount,
    COALESCE(SUM(CASE WHEN DATE(sp.start_time) BETWEEN #{thisWeekStart} AND #{today}
        THEN TIMESTAMPDIFF(SECOND, sp.start_time, sp.end_time) ELSE 0 END) / 60, 0) AS thisWeekDuration,

    COUNT(DISTINCT CASE WHEN DATE(sp.start_time) BETWEEN #{lastWeekStart} AND #{lastWeekEnd}
        THEN sp.id END) AS lastWeekSessionCount,
    COALESCE(SUM(CASE WHEN DATE(sp.start_time) BETWEEN #{lastWeekStart} AND #{lastWeekEnd}
        THEN TIMESTAMPDIFF(SECOND, sp.start_time, sp.end_time) ELSE 0 END) / 60, 0) AS lastWeekDuration,

    COUNT(DISTINCT CASE WHEN DATE(sp.start_time) BETWEEN #{thisMonthStart} AND #{today}
        THEN sp.id END) AS thisMonthSessionCount,
    COALESCE(SUM(CASE WHEN DATE(sp.start_time) BETWEEN #{thisMonthStart} AND #{today}
        THEN TIMESTAMPDIFF(SECOND, sp.start_time, sp.end_time) ELSE 0 END) / 60, 0) AS thisMonthDuration,

    COUNT(DISTINCT CASE WHEN DATE(sp.start_time) BETWEEN #{lastMonthStart} AND #{lastMonthEnd}
        THEN sp.id END) AS lastMonthSessionCount,
    COALESCE(SUM(CASE WHEN DATE(sp.start_time) BETWEEN #{lastMonthStart} AND #{lastMonthEnd}
        THEN TIMESTAMPDIFF(SECOND, sp.start_time, sp.end_time) ELSE 0 END) / 60, 0) AS lastMonthDuration
FROM schedule_performance sp
    inner join schedule_performance_staff sps on sp.id = sps.schedule_performance_id
WHERE sp.tenant_id = #{tenantId}
  AND sp.is_deleted = 0
  AND sps.is_deleted = 0
  AND sps.position_code = 'anchor'
  AND DATE(sp.start_time) BETWEEN #{lastMonthStart} AND #{today}

      AND

          sp.company_id
          sp.dept_id
          sp.team_id
          sp.live_room_id
          sp.company_id
       = #{sourceId}
